<script lang="ts">
  import { fly, slide } from 'svelte/transition';
  import { cubicOut } from 'svelte/easing';
  import { settings, saveSettings } from '../stores/settings.svelte';

  let settingsOpen = $state(false);
  let colorPickerOpen = $state(false);

  $effect(() => {
    if (!settingsOpen) return;
    const handler = (e: MouseEvent) => {
      const inSettings = e.composedPath().some(
        el => (el as Element).classList?.contains('settings-area')
      );
      if (!inSettings) {
        settingsOpen = false;
        colorPickerOpen = false;
      }
    };
    const id = setTimeout(() => window.addEventListener('click', handler), 0);
    return () => {
      clearTimeout(id);
      window.removeEventListener('click', handler);
    };
  });

  const ACCENT_COLORS = ['#ffc31c', '#f08400', '#fe4796', '#92b731', '#9754f3', '#5798ff'];

  let dateStr = $derived(
    new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' })
      .toLowerCase()
      .replace(',', '')
  );

  function toggleSettings() {
    settingsOpen = !settingsOpen;
    if (!settingsOpen) colorPickerOpen = false;
  }

  function toggleSound() {
    settings.audioEnabled = !settings.audioEnabled;
    saveSettings();
  }

  function toggleTheme() {
    settings.theme = settings.theme === 'dark' ? 'light' : 'dark';
    saveSettings();
  }

  function toggleColorPicker() {
    colorPickerOpen = !colorPickerOpen;
  }

  function setAccent(color: string) {
    settings.accentColor = color;
    saveSettings();
  }
</script>

