          <path d="M9.0126 18.5333C8.63445 18.5333 8.30882 18.4053 8.03571 18.1493C7.7626 17.8933 7.59804 17.5804 7.54202 17.2107L7.35294 15.8027C7.17087 15.7316 6.9993 15.6462 6.83824 15.5467C6.67717 15.4471 6.51961 15.3404 6.36555 15.2267L5.06303 15.7813C4.71289 15.9378 4.36275 15.952 4.01261 15.824C3.66247 15.696 3.38936 15.4684 3.19328 15.1413L2.20588 13.392C2.0098 13.0649 1.95378 12.7164 2.03782 12.3467C2.12185 11.9769 2.31092 11.6711 2.60504 11.4293L3.71849 10.576C3.70448 10.4764 3.69748 10.3804 3.69748 10.288V9.71199C3.69748 9.61955 3.70448 9.52355 3.71849 9.42399L2.60504 8.57066C2.31092 8.32888 2.12185 8.0231 2.03782 7.65333C1.95378 7.28355 2.0098 6.9351 2.20588 6.60799L3.19328 4.85866C3.38936 4.53155 3.66247 4.30399 4.01261 4.17599C4.36275 4.04799 4.71289 4.06222 5.06303 4.21866L6.36555 4.77333C6.51961 4.65955 6.68067 4.55288 6.84874 4.45333C7.01681 4.35377 7.18487 4.26844 7.35294 4.19733L7.54202 2.78933C7.59804 2.41955 7.7626 2.10666 8.03571 1.85066C8.30882 1.59466 8.63445 1.46666 9.0126 1.46666H10.9874C11.3655 1.46666 11.6912 1.59466 11.9643 1.85066C12.2374 2.10666 12.402 2.41955 12.458 2.78933L12.6471 4.19733C12.8291 4.26844 13.0007 4.35377 13.1618 4.45333C13.3228 4.55288 13.4804 4.65955 13.6345 4.77333L14.937 4.21866C15.2871 4.06222 15.6373 4.04799 15.9874 4.17599C16.3375 4.30399 16.6106 4.53155 16.8067 4.85866L17.7941 6.60799C17.9902 6.9351 18.0462 7.28355 17.9622 7.65333C17.8782 8.0231 17.6891 8.32888 17.395 8.57066L16.2815 9.42399C16.2955 9.52355 16.3025 9.61955 16.3025 9.71199V10.288C16.3025 10.3804 16.2885 10.4764 16.2605 10.576L17.3739 11.4293C17.6681 11.6711 17.8571 11.9769 17.9412 12.3467C18.0252 12.7164 17.9692 13.0649 17.7731 13.392L16.7647 15.1413C16.5686 15.4684 16.2955 15.696 15.9454 15.824C15.5952 15.952 15.2451 15.9378 14.895 15.7813L13.6345 15.2267C13.4804 15.3404 13.3193 15.4471 13.1513 15.5467C12.9832 15.6462 12.8151 15.7316 12.6471 15.8027L12.458 17.2107C12.402 17.5804 12.2374 17.8933 11.9643 18.1493C11.6912 18.4053 11.3655 18.5333 10