        </svg>
      </button>

      {#if colorPickerOpen}
        <div class="color-row" transition:fly={{ y: 4, duration: 160, easing: cubicOut }}>
          {#each ACCENT_COLORS as color}
            <button
              class="color-swatch"
              class:selected={settings.accentColor === color}
              style:--swatch={color}
              onclick={() => setAccent(color)}
              title={color}
            ></button>
          {/each}
        </div>
      {/if}
    </div>
  </div>
</div>

<style>
  .bottom-bar {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 100;
    background: var(--bg);
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    padding: 0 var(--spacing-xl);
  }

  .bottom-row {
    position: relative;
    height: 80px;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .date {
    font-family: 'Geist Mono', monospace;
    font-size: 12px;
    color: var(--text);
  }

  .settings-area {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
  }

  .actions-container {
    display: flex;
    align-items: center;
    background: var(--border);
    border-radius: var(--radius-sm);
  }

  .bar-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    background: none;
    border: none;
    border-radius: var(--radius-sm);
    color: var(--text-muted);
    transition: background 0.15s, color 0.15s;
    flex-shrink: 0;
  }

  .bar-btn:hover {
    background: rgba(255, 255, 255, 0.06);
    color: var(--text);
  }

  :global([data-theme="light"]) .bar-btn:hover {
    background: #F0E5D0;
  }

  .bar-btn.palette-active {
    color: var(--accent);
  }

  .bar-btn.settings-active {
    color: var(--text);
  }

  .color-row {
    position: absolute;
    bottom: calc(100% + 6px);
    right: 38px;
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
  }

  .color-swatch {
    position: relative;
    width: 24px;
    height: 24px;
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    border-radius: 50%;
    flex-shrink: 0;
  }

  .color-swatch::before {
    content: '';
    position: absolute;
    inset: 2px;
    border-radius: 50%;
    border: 1.5px solid var(--border);
    transition: border-color 0.12s;
  }

  .color-swatch.selected::before {
    border-color: var(--swatch);
  }

  .color-swatch::after {
    content: '';
    position: absolute;
    inset: 5px;
    border-radius: 50%;
    background: var(--swatch);
    transition: transform 0.12s;
  }

  .color-swatch:hover::after {
    transform: scale(1.2);
  }
</style>
